export const getLabelValue = (label: string | React.ReactElement): string => {
  if (typeof label === 'string') {
    return label;
  }

  const { props } = label;

  let result = '';

  if (props['children']) {
    if (Array.isArray(props['children'])) {
      result = props['children'].reduce((acc, curr) => {
        acc += `${getLabelValue(curr)}`;

        return acc;
      }, '');
    } else {
      result = getLabelValue(props.children);
    }
  }

  return result;
};
